(function () {
'use strict';
const STORAGE_KEY = 'VidhiMeet_cookie_consent';
const GA_ID = 'G-7DTR2BK4ML';
window.dataLayer = window.dataLayer || [];
function gtag() { window.dataLayer.push(arguments); }
window.gtag = gtag;
gtag('consent', 'default', {
'analytics_storage': 'denied',
'ad_storage': 'denied',
'ad_user_data': 'denied',
'ad_personalization': 'denied',
'wait_for_update': 500
});
function applyAnalyticsConsent(granted) {
if (granted) {
if (!document.getElementById('ga4-script')) {
const gaScript = document.createElement('script');
gaScript.id = 'ga4-script';
gaScript.async = true;
gaScript.src = `https://www.googletagmanager.com/gtag/js?id=${GA_ID}`;
document.head.appendChild(gaScript);
gtag('js', new Date());
gtag('config', GA_ID, {
send_page_view: true,
anonymize_ip: true
});
}
gtag('consent', 'update', {
'analytics_storage': 'granted'
});
} else {
gtag('consent', 'update', {
'analytics_storage': 'denied'
});
}
}
const defaultConsent = {
necessary: true,
analytics: true,
preferences: true,
timestamp: null,
version: '1.0'
};
function getSavedConsent() {
try {
const saved = localStorage.getItem(STORAGE_KEY);
return saved ? JSON.parse(saved) : null;
} catch (e) {
console.warn('Cookie consent localStorage read error:', e);
return null;
}
}
function saveConsent(consentData) {
try {
const payload = {
...consentData,
necessary: true,
timestamp: new Date().toISOString(),
version: '1.0'
};
localStorage.setItem(STORAGE_KEY, JSON.stringify(payload));
applyAnalyticsConsent(payload.analytics);
window.dispatchEvent(new CustomEvent('cookieConsentUpdated', { detail: payload }));
return payload;
} catch (e) {
console.warn('Cookie consent localStorage write error:', e);
return consentData;
}
}
function injectDOM() {
if (document.getElementById('lg-cookie-banner')) return;
if (!document.querySelector('link[href*="cookie-consent.css"]')) {
const link = document.createElement('link');
link.rel = 'stylesheet';
link.href = 'css/cookie-consent.css';
document.head.appendChild(link);
}
const html = `
<!-- Cookie Consent Banner -->
<div id="lg-cookie-banner" class="lg-cookie-banner" role="dialog" aria-live="polite" aria-label="Cookie Privacy Notice">
<div class="lg-cookie-header">
<div class="lg-cookie-icon">🍪</div>
<h3 class="lg-cookie-title">We value your privacy</h3>
</div>
<p class="lg-cookie-text">
VidhiMeet uses essential cookies for secure login and platform operations. With your consent, we also use analytical cookies to improve performance. Read our <a href="privacy.html" target="_blank">Privacy Policy</a>.
</p>
<div class="lg-cookie-actions">
<button id="lg-cookie-accept-all" class="lg-cookie-btn lg-cookie-btn-primary">Accept All</button>
<button id="lg-cookie-reject" class="lg-cookie-btn lg-cookie-btn-secondary">Necessary Only</button>
<button id="lg-cookie-customize" class="lg-cookie-btn lg-cookie-btn-link">Preferences</button>
</div>
</div>
<!-- Cookie Preferences Modal -->
<div id="lg-cookie-modal-backdrop" class="lg-cookie-modal-backdrop" style="display:none;">
<div class="lg-cookie-modal" role="dialog" aria-modal="true" aria-labelledby="lg-cookie-modal-title">
<div class="lg-cookie-modal-header">
<h3 id="lg-cookie-modal-title" class="lg-cookie-modal-title">Cookie Preferences</h3>
<button id="lg-cookie-modal-close" class="lg-cookie-modal-close" aria-label="Close modal">×</button>
</div>
<p class="lg-cookie-modal-desc">
Customize your cookie preferences below. Essential cookies are required to run the marketplace application and cannot be disabled.
</p>
<div class="lg-cookie-categories">
<!-- Essential -->
<div class="lg-cookie-cat">
<div class="lg-cookie-cat-info">
<h4>Essential & Security (Required)</h4>
<p>Necessary for authentication, session security, payment processing, and core marketplace functionality.</p>
</div>
<label class="lg-switch">
<input type="checkbox" checked disabled>
<span class="lg-slider"></span>
</label>
</div>
<!-- Analytics -->
<div class="lg-cookie-cat">
<div class="lg-cookie-cat-info">
<h4>Analytics & Performance</h4>
<p>Helps us analyze system usage, peak consultation times, and app performance to improve user experience.</p>
</div>
<label class="lg-switch">
<input type="checkbox" id="lg-toggle-analytics">
<span class="lg-slider"></span>
</label>
</div>
<!-- Preferences -->
<div class="lg-cookie-cat">
<div class="lg-cookie-cat-info">
<h4>Functional & Preferences</h4>
<p>Remembers your UI settings, timezone preferences, and custom filter configurations.</p>
</div>
<label class="lg-switch">
<input type="checkbox" id="lg-toggle-preferences">
<span class="lg-slider"></span>
</label>
</div>
</div>
<div class="lg-cookie-modal-footer">
<button id="lg-cookie-save-prefs" class="lg-cookie-btn lg-cookie-btn-primary">Save My Choices</button>
<button id="lg-cookie-modal-accept-all" class="lg-cookie-btn lg-cookie-btn-secondary">Accept All</button>
</div>
</div>
</div>
`;
document.body.insertAdjacentHTML('beforeend', html);
}
function init() {
injectDOM();
const banner = document.getElementById('lg-cookie-banner');
const modalBackdrop = document.getElementById('lg-cookie-modal-backdrop');
const toggleAnalytics = document.getElementById('lg-toggle-analytics');
const togglePreferences = document.getElementById('lg-toggle-preferences');
const currentConsent = getSavedConsent();
if (currentConsent) {
applyAnalyticsConsent(currentConsent.analytics);
} else {
setTimeout(() => {
if (banner) banner.classList.add('visible');
}, 600);
}
document.getElementById('lg-cookie-accept-all')?.addEventListener('click', () => {
saveConsent({ necessary: true, analytics: true, preferences: true });
banner?.classList.remove('visible');
});
document.getElementById('lg-cookie-reject')?.addEventListener('click', () => {
saveConsent({ necessary: true, analytics: false, preferences: false });
banner?.classList.remove('visible');
});
document.getElementById('lg-cookie-customize')?.addEventListener('click', () => {
openModal();
});
document.getElementById('lg-cookie-modal-close')?.addEventListener('click', () => {
closeModal();
});
modalBackdrop?.addEventListener('click', (e) => {
if (e.target === modalBackdrop) closeModal();
});
document.getElementById('lg-cookie-save-prefs')?.addEventListener('click', () => {
saveConsent({
necessary: true,
analytics: toggleAnalytics ? toggleAnalytics.checked : false,
preferences: togglePreferences ? togglePreferences.checked : false
});
closeModal();
banner?.classList.remove('visible');
});
document.getElementById('lg-cookie-modal-accept-all')?.addEventListener('click', () => {
saveConsent({ necessary: true, analytics: true, preferences: true });
closeModal();
banner?.classList.remove('visible');
});
function openModal() {
const saved = getSavedConsent() || defaultConsent;
if (toggleAnalytics) toggleAnalytics.checked = saved.analytics !== false;
if (togglePreferences) togglePreferences.checked = saved.preferences !== false;
if (modalBackdrop) {
modalBackdrop.style.display = 'flex';
void modalBackdrop.offsetWidth;
modalBackdrop.classList.add('open');
}
}
function closeModal() {
if (modalBackdrop) {
modalBackdrop.classList.remove('open');
setTimeout(() => {
if (!modalBackdrop.classList.contains('open')) {
modalBackdrop.style.display = 'none';
}
}, 260);
}
}
document.addEventListener('click', (e) => {
const target = e.target.closest('a[href="#cookie-settings"], .cookie-settings-btn, #cookie-settings-btn');
if (target) {
e.preventDefault();
openModal();
}
});
}
if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', init);
} else {
init();
}
})();